// Find a Silver pre-rendered label bitmap by text and font size.
// Returns nullptr if not found.
inline const LabelBitmap* findSilverLabelBitmap(const char* text, uint16_t fontSize) {
  for (int i = 0; i < kSilverLabelBitmapCount; i++) {
    if (kSilverLabelBitmaps[i].fontSize == fontSize && strcmp(kSilverLabelBitmaps[i].text, text) == 0) {
      return &kSilverLabelBitmaps[i];
    }
  }
  return nullptr;
}
